{$ param eyebrow label="Eyebrow Text" default="" description="Small text above the title." $}
{$ param title label="Title" default="Campaign Title" description="Main banner heading." $}
{$ param subtitle label="Subtitle" default="" description="Supporting text below the title." $}
{$ param cta_label label="CTA Label" default="" description="Optional button label." $}
{$ param cta_href label="CTA URL" default="#" description="Button destination URL." $}
{$ param bg_class label="Background Classes" default="bg-primary-dark text-white" description="Tailwind background and text color classes." $}

<section class="{$= bg_class $} py-8 px-4 text-center mb-8">
  <div class="max-w-[1100px] mx-auto">
    {$ if eyebrow $}<span class="ss-xxs uppercase font-bold block mb-2">{$= eyebrow $}</span>{$ /if $}
    <h2 class="ss-large mb-2">{$= title $}</h2>
    {$ if subtitle $}<p class="ss-small mb-4">{$= subtitle $}</p>{$ /if $}
    {$ if cta_label $}<a href="{$= cta_href $}" class="btn btn-primary">{$= cta_label $}</a>{$ /if $}
  </div>
</section>
